import time

# The sandbox has no network or API key, so FakeLLM stands in for the OpenAI client.
class FakeLLM:
    def __init__(self):
        self.calls = 0

    def complete(self, message):
        self.calls += 1
        reply = "Model answer to: " + message
        return {"reply": reply, "tokens": len(message.split()) + len(reply.split())}


llm = FakeLLM()
cache = {}                       # message -> reply
stats = {"total_requests": 0, "cache_hits": 0, "total_tokens": 0}
request_log = []                 # one dict per request: {"time", "message", "tokens", "cached"}


def chat(message):
    """Body of POST /chat. Return {"reply": str, "cached": bool, "tokens": int}."""
    stats["total_requests"] += 1
    if message in cache:
        stats["cache_hits"] += 1
        result = {"reply": cache[message], "cached": True, "tokens": 0}
    else:
        answer = llm.complete(message)
        cache[message] = answer["reply"]
        stats["total_tokens"] += answer["tokens"]
        result = {"reply": answer["reply"], "cached": False, "tokens": answer["tokens"]}
    request_log.append({"time": time.time(), "message": message,
                        "tokens": result["tokens"], "cached": result["cached"]})
    return result


def get_stats():
    """Body of GET /stats."""
    total = stats["total_requests"]
    hit_rate = round(stats["cache_hits"] / total, 2) if total else 0.0
    return {"total_requests": total, "cache_hits": stats["cache_hits"],
            "hit_rate": hit_rate, "total_tokens": stats["total_tokens"]}


for msg in ["What is Python?", "What is a list?", "What is Python?"]:
    print(chat(msg))
print(get_stats())
print("log entries:", len(request_log))

